def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    centers = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            if (original[r-1][c] == original[r+1][c] == original[r][c-1] == original[r][c+1] == 3):
                centers.append((r, c, original[r][c]))
    arm_owner = {}
    center_owner = {}
    for i, (r,c,color) in enumerate(centers):
        center_owner[(r,c)] = i
        for pos in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            arm_owner[pos] = i
    out = [row[:] for row in original]
    # Horizontal beams first; vertical beams then take precedence at intersections.
    for vertical in (False, True):
        dirs = ((1,0),(-1,0)) if vertical else ((0,1),(0,-1))
        for i, (r,c,color) in enumerate(centers):
            for dr,dc in dirs:
                rr,cc = r+dr,c+dc
                while 0 <= rr < h and 0 <= cc < w:
                    if (rr,cc) in center_owner and center_owner[(rr,cc)] != i:
                        break
                    if (rr,cc) in arm_owner and arm_owner[(rr,cc)] != i:
                        break
                    if original[rr][cc] == 0:
                        out[rr][cc] = color
                    rr += dr; cc += dc
    return out

def sparse_grid(h,w, pixels):
    g=[[0]*w for _ in range(h)]
    for r,c,v in pixels:g[r][c]=v
    return g

